import { Slider as BaseSlider } from "@base-ui/react/slider";
import type { ComponentPropsWithoutRef, ElementType } from "react";
import { cn } from "../../lib/cn";
import "../../styles/slider.css";

type StaticClass<T extends ElementType> = Omit<ComponentPropsWithoutRef<T>, "className"> & {
  className?: string;
};

export interface SliderProps extends StaticClass<typeof BaseSlider.Root> {
  /** Visible label and accessible name for the slider thumb. */
  label?: string;
  /** Show the current value next to the label. */
  showValue?: boolean;
}

/**
 * Pick a number inside a range. Arrow keys, Page Up/Down, Home, and End work on
 * the thumb. Pass `value` and `onValueChange` to control it.
 */
export function Slider({ label, showValue = false, className, ...props }: SliderProps) {
  return (
    <BaseSlider.Root className={cn("eui-slider", className)} {...props}>
      {label || showValue ? (
        <div className="eui-slider__meta">
          {label ? (
            <BaseSlider.Label className="eui-slider__label">
              {label}
            </BaseSlider.Label>
          ) : null}
          {showValue ? <BaseSlider.Value className="eui-slider__value" /> : null}
        </div>
      ) : null}
      <BaseSlider.Control className="eui-slider__control">
        <BaseSlider.Track className="eui-slider__track">
          <BaseSlider.Indicator className="eui-slider__indicator" />
        </BaseSlider.Track>
        <BaseSlider.Thumb className="eui-slider__thumb" aria-label={label} />
      </BaseSlider.Control>
    </BaseSlider.Root>
  );
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Slider. The track and fill are thin bars. The thumb is a 20px disc that gets a
   focus ring; its hit area is larger than it looks, for touch. */

.eui-slider {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
}

.eui-slider__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-size: 13px;
}

.eui-slider__label {
  font-weight: 500;
  color: var(--eui-color-fg);
}

.eui-slider__value {
  color: var(--eui-color-fg-muted);
  font-variant-numeric: tabular-nums;
}

.eui-slider__control {
  position: relative;
  display: flex;
  align-items: center;
  height: 20px;
  width: 100%;
  touch-action: none;
  cursor: pointer;
}

.eui-slider__track {
  position: relative;
  width: 100%;
  height: 4px;
  border-radius: var(--eui-radius-full);
  background-color: var(--eui-color-hover);
}

/* Base UI sets position: relative and height: inherit inline. Only the color is ours. */
.eui-slider__indicator {
  border-radius: inherit;
  background-color: var(--eui-color-accent);
}

/* Base UI sets position, inset-inline-start, top and translate(-50%, -50%) inline.
   Do not add left or margin offsets here, or the thumb would be shifted twice. */
.eui-slider__thumb {
  width: 20px;
  height: 20px;
  border-radius: var(--eui-radius-full);
  background-color: var(--eui-color-bg);
  box-shadow: 0 0 0 var(--eui-border-width) var(--eui-color-border-strong), 0 1px 2px rgb(0 0 0 / 0.15);
  cursor: grab;
}

.eui-slider__thumb:focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 3px;
}

.eui-slider__thumb:active {
  cursor: grabbing;
}
